def process(socket02: float):
    """机柜1：将输入信号直接转发到输出端口。"""
    socket03 = float(socket02)
    return {"outputs": {"socket03": socket03}}

def process(socket02: float, socket03: float):
    """机柜2：按 60%/40% 融合两路输入并从 socket04 输出。"""
    socket04 = 0.6 * float(socket02) + 0.4 * float(socket03)
    return {"outputs": {"socket04": socket04}}

def process(socket03: float):
    """机柜3：对输入执行 2% 线路损耗后从 socket05 输出。"""
    socket05 = 0.98 * float(socket03)
    return {"outputs": {"socket05": socket05}}

